mapper.select:
SELECT a.id, a.biz_type, a.biz_id, a.applicant_id, a.village_id, a.audit_status, a.audit_remark, a.submit_time, a.audit_time, u.real_name AS applicant_name, u.phone AS applicant_phone, u.credit_score AS applicant_credit, u.realname_status AS realname_status, v.village_name AS applicant_village_name,
u.id_card, u.id_card_front, u.id_card_back, r.resource_name, r.cover_url AS resource_cover, r.description AS resource_description, r.price, r.price_unit, r.trade_type, r.risk_level, r.resource_status, c.category_name, au.real_name AS auditor_name
WHERE a.id = #{id}

SELECT COUNT(*)
FROM sys_audit_record a

    a.audit_status = 0

        AND a.village_id IN

            #{vid}



        AND a.biz_type = #{bizType}
